-- same logic as dws_sr_data_warehouse_platform_exp_level_nmv_1d but run for T-31 daily
create temporary view user_exp_${grass_region_without_quote} as
select
    user_id
    ,collect_list(exp_group_id) as exp_group_ids
from
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and is_assignment_log = 1
    and is_rcmd_whitelist = 1
group by user_id
;

